import { join } from "node:path";

import Root from "../../../Common/Function/Root.mjs";
import Trees from "../../../Common/Variable/Trees.mjs";

// The family ships one behavior in two release trees, so the generated table is
// written into both. The package names differ; the generated BYTES must not -
// the two Catalog.ts files are kept identical by construction, and the catalog
// check fails if either drifts.
const Package = {
	Classic: "hook-dsh-tool-coach",
	EffectTS: "ets-hook-dsh-tool-coach",
};

export default () =>
	Trees.map((Tree) =>
		join(Root, Tree, "packages", Package[Tree], "Source", "Variable", "Catalog.ts"),
	);
